import { ImageCropCanvas } from "./canvas";
import { useImageCrop } from "./context";
import { ImageCropProvider } from "./provider";

export type {
  ImageCropCanvasProps,
  ImageCropImage,
  ImageCropInitialImage,
  ImageCropOptions,
  ImageCropProviderProps,
  ImageCropResult,
} from "./types";
export { ImageCropCanvas, ImageCropProvider, useImageCrop };

import type { ComponentProps, JSX } from "solid-js";
import { mergeProps, onCleanup, onMount, Show, splitProps } from "solid-js";

import { cn } from "@/lib/utils";

import { useImageCropContext } from "./context";
import { resizeCrop } from "./geometry";
import type { ImageCropCanvasProps, ResizeHandleDirection } from "./types";

function ImageCropCanvas(props: ImageCropCanvasProps) {
  const mergedProps = mergeProps({ showResizeHandles: true }, props);
  const [local, others] = splitProps(mergedProps, ["class", "showResizeHandles"]);
  const crop = useImageCropContext();
  let viewportRef: HTMLDivElement | undefined;

  const startDrag = (event: PointerEvent) => {
    event.preventDefault();

    const start = {
      crop: crop.options(),
      pointerX: event.clientX,
      pointerY: event.clientY,
    };

    const handlePointerMove = (moveEvent: PointerEvent) => {
      const deltaX = moveEvent.clientX - start.pointerX;
      const deltaY = moveEvent.clientY - start.pointerY;

      crop.setOptions({
        ...start.crop,
        x: start.crop.x + deltaX,
        y: start.crop.y + deltaY,
      });
    };

    const handlePointerUp = () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
  };

  const startResize = (handle: ResizeHandleDirection, event: PointerEvent) => {
    event.preventDefault();
    event.stopPropagation();

    const start = {
      crop: crop.options(),
      pointerX: event.clientX,
      pointerY: event.clientY,
    };

    const handlePointerMove = (moveEvent: PointerEvent) => {
      const deltaX = moveEvent.clientX - start.pointerX;
      const deltaY = moveEvent.clientY - start.pointerY;
      const next = resizeCrop(handle, start.crop, deltaX, deltaY, crop.aspectRatio());

      crop.setOptions(next);
    };

    const handlePointerUp = () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
  };

  const handleKeyDown: JSX.EventHandler<HTMLButtonElement, KeyboardEvent> = (event) => {
    const keyOffsets: Record<string, { x: number; y: number }> = {
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 },
      ArrowUp: { x: 0, y: -1 },
    };
    const offset = keyOffsets[event.key];

    if (!offset) {
      return;
    }

    event.preventDefault();

    const step = event.shiftKey ? 10 : 1;
    crop.setOptions((previous) => ({
      ...previous,
      x: previous.x + offset.x * step,
      y: previous.y + offset.y * step,
    }));
  };

  const handleSelectionPointerDown: JSX.EventHandler<HTMLButtonElement, PointerEvent> = (event) => {
    const handle = (event.target as HTMLElement).dataset.resizeHandle as
      | ResizeHandleDirection
      | undefined;

    if (handle) {
      startResize(handle, event);
      return;
    }

    startDrag(event);
  };

  onMount(() => {
    const updateViewportSize = () => {
      if (!viewportRef) {
        return;
      }

      const rect = viewportRef.getBoundingClientRect();
      crop.setViewportSize({ height: rect.height, width: rect.width });
    };

    updateViewportSize();

    const observer = new ResizeObserver(updateViewportSize);

    if (viewportRef) {
      observer.observe(viewportRef);
    }

    onCleanup(() => observer.disconnect());
  });

  return (
    <div
      ref={viewportRef}
      data-slot="image-crop-canvas"
      class={cn(
        "flex min-h-105 flex-1 items-center justify-center overflow-hidden bg-muted/20 p-4",
        local.class,
      )}
      {...others}
    >
      <Show when={crop.image()}>
        {(image) => (
          <div
            class="relative overflow-hidden shadow-sm ring-1 ring-border"
            data-slot="image-crop-stage"
            style={{
              height: `${crop.displaySize().height}px`,
              width: `${crop.displaySize().width}px`,
            }}
          >
            <img
              alt={image().name}
              class="absolute inset-0 size-full select-none object-fill"
              draggable={false}
              src={image().src}
            />
            <button
              aria-label="Crop area"
              class="absolute touch-none appearance-none p-0 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              data-slot="image-crop-selection"
              onKeyDown={handleKeyDown}
              onPointerDown={handleSelectionPointerDown}
              style={{
                height: `${crop.options().height}px`,
                left: `${crop.options().x}px`,
                top: `${crop.options().y}px`,
                width: `${crop.options().width}px`,
              }}
              type="button"
            >
              <span class="absolute inset-0 cursor-move border-2 border-white border-dashed shadow-[0_0_0_9999px_rgb(0_0_0/0.45)] ring-1 ring-black/30" />
              <ResizeEdgeControl class="-top-2 right-2 left-2 h-4 cursor-ns-resize" handle="n" />
              <ResizeEdgeControl class="top-2 -right-2 bottom-2 w-4 cursor-ew-resize" handle="e" />
              <ResizeEdgeControl class="right-2 -bottom-2 left-2 h-4 cursor-ns-resize" handle="s" />
              <ResizeEdgeControl class="top-2 bottom-2 -left-2 w-4 cursor-ew-resize" handle="w" />
              <ResizeHandleControl
                class="-top-2 -left-2 cursor-nwse-resize"
                handle="nw"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="-top-2 left-1/2 -translate-x-1/2 cursor-ns-resize"
                handle="n"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="-top-2 -right-2 cursor-nesw-resize"
                handle="ne"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="top-1/2 -right-2 -translate-y-1/2 cursor-ew-resize"
                handle="e"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="-right-2 -bottom-2 cursor-nwse-resize"
                handle="se"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="-bottom-2 left-1/2 -translate-x-1/2 cursor-ns-resize"
                handle="s"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="-bottom-2 -left-2 cursor-nesw-resize"
                handle="sw"
                visible={local.showResizeHandles}
              />
              <ResizeHandleControl
                class="top-1/2 -left-2 -translate-y-1/2 cursor-ew-resize"
                handle="w"
                visible={local.showResizeHandles}
              />
            </button>
          </div>
        )}
      </Show>
    </div>
  );
}

function ResizeEdgeControl(
  props: ComponentProps<"span"> & {
    handle: ResizeHandleDirection;
  },
) {
  const [local, others] = splitProps(props, ["class", "handle"]);

  return (
    <span
      aria-hidden="true"
      class={cn("absolute z-10", local.class)}
      data-resize-handle={local.handle}
      {...others}
    />
  );
}

function ResizeHandleControl(
  props: ComponentProps<"span"> & {
    handle: ResizeHandleDirection;
    visible: boolean;
  },
) {
  const [local, others] = splitProps(props, ["class", "handle", "visible"]);

  return (
    <span
      aria-hidden="true"
      class={cn("absolute z-20 flex size-4 items-center justify-center", local.class)}
      data-resize-handle={local.handle}
      {...others}
    >
      <Show when={local.visible}>
        <span
          class="pointer-events-none size-2.5 rounded-full border border-background bg-primary shadow-sm ring-1 ring-black/20"
          data-resize-handle-indicator=""
        />
      </Show>
    </span>
  );
}

export { ImageCropCanvas };

const DEFAULT_CROP_SIZE = 120;
const DEFAULT_CROP_RATIO = 0.72;
const DEFAULT_ASPECT_RATIO = 1;
const MAX_STAGE_WIDTH_RATIO = 0.92;
const MAX_STAGE_HEIGHT_RATIO = 0.9;

export {
  DEFAULT_ASPECT_RATIO,
  DEFAULT_CROP_RATIO,
  DEFAULT_CROP_SIZE,
  MAX_STAGE_HEIGHT_RATIO,
  MAX_STAGE_WIDTH_RATIO,
};

import { createContext, useContext } from "solid-js";

import type { ImageCropContextValue } from "./types";

const ImageCropContext = createContext<ImageCropContextValue | null>(null);

function useImageCropContext() {
  const context = useContext(ImageCropContext);

  if (!context) {
    throw new Error("useImageCrop must be used within an ImageCropProvider.");
  }

  return context;
}

function useImageCrop(): Omit<ImageCropContextValue, "setViewportSize"> {
  const { setViewportSize: _setViewportSize, ...context } = useImageCropContext();

  return context;
}

export { ImageCropContext, useImageCrop, useImageCropContext };

import {
  DEFAULT_CROP_RATIO,
  DEFAULT_CROP_SIZE,
  MAX_STAGE_HEIGHT_RATIO,
  MAX_STAGE_WIDTH_RATIO,
} from "./constants";
import type { ImageCropImage, ImageCropOptions, ResizeHandleDirection } from "./types";

const defaultOptions: ImageCropOptions = {
  height: DEFAULT_CROP_SIZE,
  original: true,
  width: DEFAULT_CROP_SIZE,
  x: 0,
  y: 0,
};

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

function roundPixel(value: number) {
  return Math.max(0, Math.round(value));
}

function roundDimension(value: number) {
  return Math.max(1, roundPixel(value));
}

function getAspectRatio(value: number | null | undefined) {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
    return null;
  }

  return value;
}

function getFallbackViewportSize() {
  if (typeof window === "undefined") {
    return { height: 720, width: 960 };
  }

  return {
    height: window.innerHeight * 0.78,
    width: window.innerWidth * 0.78,
  };
}

function calculateScaleFactor(
  image: Pick<ImageCropImage, "height" | "width">,
  viewportSize: { height: number; width: number },
) {
  const fallback = getFallbackViewportSize();
  const availableWidth = Math.max(
    1,
    (viewportSize.width || fallback.width) * MAX_STAGE_WIDTH_RATIO,
  );
  const availableHeight = Math.max(
    1,
    (viewportSize.height || fallback.height) * MAX_STAGE_HEIGHT_RATIO,
  );
  const widthRatio = availableWidth / image.width;
  const heightRatio = availableHeight / image.height;

  return Math.min(1, widthRatio, heightRatio);
}

function getDisplaySize(image: Pick<ImageCropImage, "height" | "width"> | null, scale: number) {
  if (!image) {
    return { height: 0, width: 0 };
  }

  return {
    height: Math.max(1, Math.floor(image.height * scale)),
    width: Math.max(1, Math.floor(image.width * scale)),
  };
}

function clampCropOptions(
  options: ImageCropOptions,
  bounds: { height: number; width: number },
  aspectRatio: number | null = null,
): ImageCropOptions {
  if (bounds.width <= 0 || bounds.height <= 0) {
    return { ...defaultOptions, original: options.original };
  }

  let width = clamp(roundPixel(options.width), 1, bounds.width);
  let height = clamp(roundPixel(options.height), 1, bounds.height);

  if (aspectRatio) {
    const widthCandidate = {
      height: roundDimension(width / aspectRatio),
      width,
    };
    const heightCandidate = {
      height,
      width: roundDimension(height * aspectRatio),
    };
    const candidates = [widthCandidate, heightCandidate].filter(
      (candidate) => candidate.width <= bounds.width && candidate.height <= bounds.height,
    );
    const bestSize =
      candidates.sort(
        (a, b) =>
          Math.abs(a.width - options.width) +
          Math.abs(a.height - options.height) -
          (Math.abs(b.width - options.width) + Math.abs(b.height - options.height)),
      )[0] ?? getLargestAspectSize(bounds, aspectRatio);

    width = bestSize.width;
    height = bestSize.height;
  }

  const x = clamp(roundPixel(options.x), 0, bounds.width - width);
  const y = clamp(roundPixel(options.y), 0, bounds.height - height);

  return {
    height,
    original: options.original,
    width,
    x,
    y,
  };
}

function getLargestAspectSize(bounds: { height: number; width: number }, aspectRatio: number) {
  let width = Math.max(1, bounds.width);
  let height = width / aspectRatio;

  if (height > bounds.height) {
    height = Math.max(1, bounds.height);
    width = height * aspectRatio;
  }

  return {
    height: roundDimension(height),
    width: roundDimension(width),
  };
}

function getDefaultOptions(
  bounds: { height: number; width: number },
  aspectRatio: number | null = null,
): ImageCropOptions {
  const defaultSize = aspectRatio
    ? getLargestAspectSize(bounds, aspectRatio)
    : {
        height: Math.min(DEFAULT_CROP_SIZE, Math.max(1, bounds.height)),
        width: Math.min(DEFAULT_CROP_SIZE, Math.max(1, bounds.width)),
      };
  const width = aspectRatio
    ? roundDimension(defaultSize.width * DEFAULT_CROP_RATIO)
    : defaultSize.width;
  const height = aspectRatio ? roundDimension(width / aspectRatio) : defaultSize.height;

  return {
    height,
    original: true,
    width,
    x: Math.max(0, Math.floor((bounds.width - width) / 2)),
    y: Math.max(0, Math.floor((bounds.height - height) / 2)),
  };
}

function resizeCrop(
  handle: ResizeHandleDirection,
  crop: ImageCropOptions,
  deltaX: number,
  deltaY: number,
  aspectRatio: number | null = null,
) {
  if (aspectRatio) {
    const resizesHorizontally = handle.includes("e") || handle.includes("w");
    const resizesVertically = handle.includes("n") || handle.includes("s");
    const widthFromHorizontal = handle.includes("w") ? crop.width - deltaX : crop.width + deltaX;
    const heightFromVertical = handle.includes("n") ? crop.height - deltaY : crop.height + deltaY;
    const widthFromVertical = heightFromVertical * aspectRatio;
    let width = crop.width;

    if (resizesHorizontally && resizesVertically) {
      width =
        Math.abs(widthFromHorizontal - crop.width) >= Math.abs(widthFromVertical - crop.width)
          ? widthFromHorizontal
          : widthFromVertical;
    } else if (resizesHorizontally) {
      width = widthFromHorizontal;
    } else if (resizesVertically) {
      width = widthFromVertical;
    }

    const height = width / aspectRatio;
    let x = crop.x;
    let y = crop.y;

    if (handle.includes("w")) {
      x = crop.x + crop.width - width;
    } else if (!handle.includes("e")) {
      x = crop.x + (crop.width - width) / 2;
    }

    if (handle.includes("n")) {
      y = crop.y + crop.height - height;
    } else if (!handle.includes("s")) {
      y = crop.y + (crop.height - height) / 2;
    }

    return {
      ...crop,
      height,
      width,
      x,
      y,
    };
  }

  let { height, width, x, y } = crop;

  if (handle.includes("e")) {
    width += deltaX;
  }

  if (handle.includes("s")) {
    height += deltaY;
  }

  if (handle.includes("w")) {
    x += deltaX;
    width -= deltaX;
  }

  if (handle.includes("n")) {
    y += deltaY;
    height -= deltaY;
  }

  return {
    ...crop,
    height,
    width,
    x,
    y,
  };
}

export {
  calculateScaleFactor,
  clampCropOptions,
  defaultOptions,
  getAspectRatio,
  getDefaultOptions,
  getDisplaySize,
  getFallbackViewportSize,
  resizeCrop,
};

import type { ImageCropImage, ImageCropInitialImage } from "./types";

function getImageDimensions(src: string) {
  return new Promise<{ height: number; width: number }>((resolve, reject) => {
    const img = new Image();

    img.onload = () => {
      resolve({ height: img.naturalHeight, width: img.naturalWidth });
    };
    img.onerror = () => reject(new Error("Unable to load image dimensions."));
    img.src = src;
  });
}

function loadCanvasImage(src: string) {
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();

    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Unable to load image for cropping."));
    img.src = src;
  });
}

async function createImageFromFile(file: File): Promise<ImageCropImage> {
  const src = URL.createObjectURL(file);

  try {
    const dimensions = await getImageDimensions(src);

    return {
      ...dimensions,
      name: file.name || "image",
      revoke: () => URL.revokeObjectURL(src),
      src,
      type: file.type || "image/png",
    };
  } catch (error) {
    URL.revokeObjectURL(src);
    throw error;
  }
}

async function createImageFromSource(source: ImageCropInitialImage): Promise<ImageCropImage> {
  const dimensions = await getImageDimensions(source.src);

  return {
    ...dimensions,
    name: source.name ?? "image",
    src: source.src,
    type: source.type ?? "image/png",
  };
}

export { createImageFromFile, createImageFromSource, loadCanvasImage };

import type { ParentProps } from "solid-js";
import {
  createEffect,
  createMemo,
  createSignal,
  mergeProps,
  onCleanup,
  onMount,
  splitProps,
  untrack,
} from "solid-js";

import { DEFAULT_ASPECT_RATIO } from "./constants";
import { ImageCropContext } from "./context";
import {
  calculateScaleFactor,
  clampCropOptions,
  defaultOptions,
  getAspectRatio,
  getDefaultOptions,
  getDisplaySize,
  getFallbackViewportSize,
} from "./geometry";
import { createImageFromFile, createImageFromSource, loadCanvasImage } from "./image-utils";
import type {
  ImageCropImage,
  ImageCropInitialImage,
  ImageCropOptions,
  ImageCropProviderProps,
  ImageCropResult,
} from "./types";

function ImageCropProvider(props: ParentProps<ImageCropProviderProps>) {
  const mergedProps = mergeProps(
    {
      aspectRatio: DEFAULT_ASPECT_RATIO,
      outputQuality: 0.92,
      outputType: "image/png" as const,
    },
    props,
  );
  const [local] = splitProps(mergedProps, [
    "aspectRatio",
    "children",
    "defaultImage",
    "onCrop",
    "outputQuality",
    "outputType",
  ]);

  const [image, setImage] = createSignal<ImageCropImage | null>(null);
  const [options, setOptionsSignal] = createSignal(defaultOptions);
  const [viewportSize, setViewportSize] = createSignal(getFallbackViewportSize());
  const [lastScaleFactor, setLastScaleFactor] = createSignal(1);
  const [isCropping, setIsCropping] = createSignal(false);
  const aspectRatio = createMemo(() => getAspectRatio(local.aspectRatio));

  const scaleFactor = createMemo(() => {
    const currentImage = image();

    if (!currentImage) {
      return 1;
    }

    return calculateScaleFactor(currentImage, viewportSize());
  });

  const displaySize = createMemo(() => getDisplaySize(image(), scaleFactor()));

  const setOptions = (
    value: ImageCropOptions | ((previous: ImageCropOptions) => ImageCropOptions),
  ) => {
    setOptionsSignal((previous) => {
      const next = typeof value === "function" ? value(previous) : value;
      return clampCropOptions(next, displaySize(), aspectRatio());
    });
  };

  const replaceImage = (nextImage: ImageCropImage | null) => {
    setImage((previous) => {
      previous?.revoke?.();
      return nextImage;
    });
  };

  const resetCrop = () => {
    setOptionsSignal(getDefaultOptions(displaySize(), aspectRatio()));
  };

  const setImageAndResetCrop = (nextImage: ImageCropImage) => {
    const nextScale = calculateScaleFactor(nextImage, viewportSize());
    const nextSize = getDisplaySize(nextImage, nextScale);

    setLastScaleFactor(nextScale);
    replaceImage(nextImage);
    setOptionsSignal(getDefaultOptions(nextSize, aspectRatio()));
  };

  const setImageFromFile = async (file: File) => {
    if (!file.type.startsWith("image/")) return;
    const nextImage = await createImageFromFile(file);
    setImageAndResetCrop(nextImage);
  };

  const setImageFromSource = async (source: ImageCropInitialImage) => {
    const nextImage = await createImageFromSource(source);
    setImageAndResetCrop(nextImage);
  };

  const cropImage = async () => {
    const currentImage = image();

    if (!currentImage || untrack(isCropping)) return null;

    setIsCropping(true);

    try {
      const currentOptions = options();
      const currentScale = scaleFactor();
      const sourceCrop = {
        height: currentOptions.height / currentScale,
        width: currentOptions.width / currentScale,
        x: currentOptions.x / currentScale,
        y: currentOptions.y / currentScale,
      };
      const outputWidth = Math.max(
        1,
        Math.round(currentOptions.original ? sourceCrop.width : currentOptions.width),
      );
      const outputHeight = Math.max(
        1,
        Math.round(currentOptions.original ? sourceCrop.height : currentOptions.height),
      );
      const canvas = document.createElement("canvas");
      const context = canvas.getContext("2d");

      if (!context) return null;

      const img = await loadCanvasImage(currentImage.src);
      canvas.width = outputWidth;
      canvas.height = outputHeight;
      context.drawImage(
        img,
        sourceCrop.x,
        sourceCrop.y,
        sourceCrop.width,
        sourceCrop.height,
        0,
        0,
        outputWidth,
        outputHeight,
      );

      const dataUrl = canvas.toDataURL(local.outputType, local.outputQuality);
      const response = await fetch(dataUrl);
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const result: ImageCropResult = {
        blob,
        dataUrl,
        height: outputHeight,
        options: currentOptions,
        revoke: () => URL.revokeObjectURL(url),
        url,
        width: outputWidth,
      };

      local.onCrop?.(result);

      return result;
    } finally {
      setIsCropping(false);
    }
  };

  createEffect(() => {
    const currentImage = image();
    const nextScale = scaleFactor();
    const previousScale = lastScaleFactor();

    if (!currentImage || previousScale <= 0 || nextScale === previousScale) {
      setLastScaleFactor(nextScale);
      return;
    }

    const ratio = nextScale / previousScale;
    setLastScaleFactor(nextScale);
    setOptionsSignal((previous) =>
      clampCropOptions(
        {
          ...previous,
          height: Math.floor(previous.height * ratio),
          width: Math.floor(previous.width * ratio),
          x: Math.floor(previous.x * ratio),
          y: Math.floor(previous.y * ratio),
        },
        getDisplaySize(currentImage, nextScale),
        aspectRatio(),
      ),
    );
  });

  onMount(() => {
    if (!local.defaultImage) return;
    void setImageFromSource(local.defaultImage);
  });

  onCleanup(() => {
    image()?.revoke?.();
  });

  return (
    <ImageCropContext.Provider
      value={{
        aspectRatio,
        cropImage,
        displaySize,
        image,
        isCropping,
        options,
        resetCrop,
        setImageFromFile,
        setImageFromSource,
        setOptions,
        setViewportSize,
      }}
    >
      {local.children}
    </ImageCropContext.Provider>
  );
}

export { ImageCropProvider };

import type { Accessor, ComponentProps } from "solid-js";

type ImageCropImage = {
  height: number;
  name: string;
  src: string;
  type: string;
  width: number;
  revoke?: () => void;
};

type ImageCropInitialImage = {
  name?: string;
  src: string;
  type?: string;
};

type ImageCropOptions = {
  height: number;
  original: boolean;
  width: number;
  x: number;
  y: number;
};

type ImageCropResult = {
  blob: Blob;
  dataUrl: string;
  height: number;
  options: ImageCropOptions;
  revoke: () => void;
  url: string;
  width: number;
};

type ImageCropContextValue = {
  aspectRatio: Accessor<number | null>;
  cropImage: () => Promise<ImageCropResult | null>;
  displaySize: Accessor<{ height: number; width: number }>;
  image: Accessor<ImageCropImage | null>;
  isCropping: Accessor<boolean>;
  options: Accessor<ImageCropOptions>;
  resetCrop: () => void;
  setImageFromFile: (file: File) => Promise<void>;
  setImageFromSource: (source: ImageCropInitialImage) => Promise<void>;
  setOptions: (
    value: ImageCropOptions | ((previous: ImageCropOptions) => ImageCropOptions),
  ) => void;
  setViewportSize: (size: { height: number; width: number }) => void;
};

type ImageCropCanvasProps = ComponentProps<"div"> & {
  showResizeHandles?: boolean;
};

type ResizeHandleDirection = "e" | "n" | "ne" | "nw" | "s" | "se" | "sw" | "w";

type ImageCropProviderProps = {
  aspectRatio?: number | null;
  defaultImage?: ImageCropInitialImage;
  onCrop?: (result: ImageCropResult) => void;
  outputQuality?: number;
  outputType?: "image/jpeg" | "image/png" | "image/webp";
};

export type {
  ImageCropCanvasProps,
  ImageCropContextValue,
  ImageCropImage,
  ImageCropInitialImage,
  ImageCropOptions,
  ImageCropProviderProps,
  ImageCropResult,
  ResizeHandleDirection,
};
